export type TechIcon = { color: string; path: string };

export function getTechIcon(label: string): TechIcon | undefined {
  let best: { index: number; icon: TechIcon } | undefined;

  for (const rule of rules) {
    const match = label.match(rule.pattern);
    if (match?.index !== undefined && (!best || match.index < best.index)) {
      best = { index: match.index, icon: { color: rule.color, path: rule.path } };
    }
  }

  return best?.icon;
}
